#include <stdio.h>
#include <string.h>

static int is_ws(char c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f';
}

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    const char *in = argv[1];
    size_t len = strlen(in);
    if (len > 1024) len = 1024; // limit as in original binary
    char out[1025];
    size_t out_idx = 0;
    int seen_nonspace = 0; // whether we have output any non‑whitespace character yet
    int in_space = 0;      // whether the current input position is within a whitespace run
    for (size_t i = 0; i < len; ++i) {
        char c = in[i];
        if (is_ws(c)) {
            in_space = 1;
        } else {
            if (in_space && seen_nonspace) {
                // collapse a run of whitespace to a single space
                out[out_idx++] = ' ';
            }
            out[out_idx++] = c;
            seen_nonspace = 1;
            in_space = 0;
        }
    }
    out[out_idx] = '\0';
    if (out_idx == 0) {
        puts("EMPTY");
    } else {
        puts(out);
    }
    return 0;
}
